/*
 * emilayout.h - how an entity is laid out: its scalar fields (flattened objects included) as a list of
 * columns with the json path of their value, and its arrays of objects as child layouts. The generated
 * entity headers carry that as const tables; emisql.h (SQLite) and emipack.h (compact binary) walk it.
 * No SQLite needed here.
 *
 * Generated by the Emi compiler - do not edit by hand.
 */
#ifndef EMISDK_EMILAYOUT_H
#define EMISDK_EMILAYOUT_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "cjson/cJSON.h"

typedef enum EmiSqlKind {
    EMISQL_STRING = 0,
    EMISQL_INT,
    EMISQL_FLOAT,
    EMISQL_BOOL,
    EMISQL_JSON, /* any json value, kept as text */
    EMISQL_TIME, /* RFC 3339 string */
    EMISQL_DATE  /* YYYY-MM-DD string */
} EmiSqlKind;

/* One column and the json path of its value inside the row's object. */
typedef struct EmiSqlColumn {
    const char* column;
    EmiSqlKind kind;
    const char* const* path;
    size_t depth;
} EmiSqlColumn;

struct EmiSqlLayout;

/* An array of objects: the json path to the array, and the table of its elements. */
typedef struct EmiSqlChild {
    const char* const* path;
    size_t depth;
    const struct EmiSqlLayout* layout;
} EmiSqlChild;

typedef struct EmiSqlLayout {
    const char* table;
    const EmiSqlColumn* columns;
    size_t column_count;
    const EmiSqlChild* children;
    size_t child_count;
} EmiSqlLayout;

static inline const cJSON* emisql_json_get(const cJSON* root, const char* const* path, size_t depth) {
    const cJSON* cur = root;
    for (size_t i = 0; i < depth && cur; i++) {
        if (!cJSON_IsObject(cur)) return NULL;
        cur = cJSON_GetObjectItemCaseSensitive(cur, path[i]);
    }
    return cur;
}

/* Puts item (ownership moves) at the path, creating the objects on the way. */
static inline int emisql_json_set(cJSON* root, const char* const* path, size_t depth, cJSON* item) {
    cJSON* cur = root;
    for (size_t i = 0; i + 1 < depth; i++) {
        cJSON* next = cJSON_GetObjectItemCaseSensitive(cur, path[i]);
        if (!next) {
            next = cJSON_CreateObject();
            if (!next) { cJSON_Delete(item); return -1; }
            cJSON_AddItemToObject(cur, path[i], next);
        } else if (!cJSON_IsObject(next)) {
            cJSON_Delete(item);
            return -1;
        }
        cur = next;
    }
    cJSON_AddItemToObject(cur, path[depth - 1], item);
    return 0;
}

#endif /* EMISDK_EMILAYOUT_H */
